// รูปแบบข้อสอบ: [ "โจทย์", ["ตัวเลือก ก","ตัวเลือก ข","ตัวเลือก ค","ตัวเลือก ง"], ข้อที่ถูก ]
// ข้อที่ถูกนับจาก 0  (0=ก, 1=ข, 2=ค, 3=ง)
// ใส่ <u>ข้อความ</u> ในโจทย์ได้ถ้าต้องการขีดเส้นใต้
// ข้อควรระวัง: เพิ่มข้อ/ชุดใหม่ "ต่อท้าย" เสมอ อย่าแทรกกลางหรือสลับลำดับ ไม่งั้นความคืบหน้าที่เคยทำไว้จะเพี้ยน

// ---------- บทความประกอบโจทย์ (ใช้ซ้ำในหลายข้อ) ----------
const S6_P9 = "ลูกชายชาวนาคนหนึ่งออกไปหาหอยทาก ครั้นได้หอยทากเต็มสองอุ้งมือแล้วก็ก่อไฟขึ้น เพื่อย่างหอยทากเหล่านั้นเมื่อไฟลุกโชนหอยทากก็เริ่มรู้สึก พวกมันเริ่มหดตัวเข้าไปในเปลือกมากขึ้นๆและมีเสียงแฉ่ ๆ ดังออกมา ทุกครั้งที่ทำเช่นนั้น เมื่อเด็กชายได้ยินเสียงดังกล่าวก็พูด “เจ้าสัตว์ประหลาด พวกเจ้ายังมีกะจิตกะใจผิวปากเล่น ขณะที่บ้านของเจ้ากำลังถูกไฟไหม้รึ”";
const S6_P20 = "“…ป่าชายเลนนี้สำคัญในการที่จะรักษาเอาไว้ เพื่อรักษาพันธุ์ปลาพันธุ์กุ้ง ปู ปลา ให้มีมากเหมือนแต่เก่าแต่ก่อน ขณะนี้ป่าชายเลนถูกทำลายมากมายก่ายกอง เราน่าจะสอนลูกหลานเราให้รู้ถึงคุณค่าของป่าชายเลนที่มีประโยชน์ต่อคนไทยทุกคนในแผ่นดินนี้”";

const S7_P23 = "“…Oshino Hakkai (忍野八海) หรือที่คนไทยเรียกกันติดปากว่า หมู่บ้านน้ำใส นั้นตั้งอยู่ที่จังหวัดยามานาชิ ในเขตพื้นที่เดียวกันกับทะเลสาบทั้ง 5 ที่ล้อมรอบภูเขาไฟฟูจิเอาไว้นั่นเอง นักท่องเที่ยวที่เดินทางมาเที่ยวชมภูเขาไฟฟูจิจึงนิยมเดินทางมาที่หมู่บ้านน้ำใสแห่งนี้ด้วย ที่นี่มีความสวยงามในระดับที่ว่าได้รับการขึ้นทะเบียนให้เป็นมรดกทางธรรมชาติในปี ค.ศ. 1934 และได้รับคัดเลือกให้เป็นหนึ่งในภูมิทัศน์ทางน้ำที่งดงามร้อยอันดับในปี ค.ศ. 1985 อีกด้วย<br><br>ที่นี่เป็นหมู่บ้านเล็ก ๆ ที่เล่าขานกันมาว่าแต่เดิมเป็นพื้นที่ของทะเลสาบรอบภูเขาไฟฟูจิ แต่เมื่อกาลเวลาผ่านไป ทำให้ทะเลสาบเหล่านั้นมีการเหือดแห้งไปตามธรรมชาติเมื่อเวลากว่าหลายร้อยปีที่ผ่านมา และสิ่งที่เหลืออยู่ก็คือบ่อน้ำทั้ง 8 บ่อที่บรรจุน้ำที่ใสสมชื่อหมู่บ้านเอาไว้เต็มเปี่ยม ซึ่งน้ำใสในบ่อทั้ง 8 นี้ คือน้ำที่เกิดจากการละลายของหิมะบนภูเขาไฟในช่วงฤดูร้อน ไหลผ่านหินลาวาที่มีรูพรุนรวมกับแร่ธาตุต่าง ๆ ทำให้น้ำนั้นใสแจ๋วอย่างที่เราเห็น คนญี่ปุ่นมีความเชื่อว่าน้ำใน 8 บ่อนี้ไม่ใช่แค่น้ำที่ใสสะอาดและเย็นฉ่ำเท่านั้น แต่มีความศักดิ์สิทธิ์ที่หากใครได้ดื่มกินจะมีอายุยืนยาว ปราศจากโรคภัยไข้เจ็บ ซึ่งนักท่องเที่ยวอย่างเราสามารถวักน้ำจากในบ่อขึ้นมาดื่มได้ หรือถ้าหากอยากเก็บกลับไปเป็นที่ระลึกหรือของฝากก็สามารถซื้อขวดจากร้านค้าบริเวณนั้นแล้วกรอกน้ำใส่ขวดกลับไปได้...”";

const S8_P1 = "เมื่อสุนัขตกจากสะพานชำรุดสู่ลำน้ำ มันรีบว่ายขึ้นฝั่ง เชิดหน้า สะบัดขน ไม่บ่นว่า หรือด่าทอสะพาน และก็ไม่ร้องขานแก้ตัว ไม่มีสัตว์โลกชนิดใดเลย ที่จะแก้ตัวให้กับความผิดพลาดของมัน มันจะทำในสิ่งที่เหมาะสมกว่า นั่นคือ เริ่มต้นใหม่อย่างไม่ประมาท เมื่อบริสุทธิ์อย่างแท้จริง ไยต้องพะวงกับการกล่าวหา ยามผิดพลาดอย่าพะวงถึงการแก้ตัว ใช้รอย และการกระทำดีแทนการแก้ตัวเถิด";
const S8_P3 = "“เมื่อมีโอกาสและมีงานทำ ควรเต็มใจทำโดยไม่จำเป็นต้องตั้งข้อแม้<br>หรือเงื่อนไขอันใดไว้ให้กีดขวาง<br>คนที่ทำงานได้จริง ๆ นั้น ไม่ว่าจะจับงานสิ่งใด ย่อมทำได้เสมอ”<br>(พระบรมราโชวาทในรัชกาลที่ 9)";
const S8_P4 = "“อย่าบังคับ อย่ายัดเยียด คาดหวังให้ลูกต้องเป็นเด็กรักการอ่าน แต่ควรช่วยเหลือโดยการจัดสิ่งแวดล้อมที่เอื้อกับการอ่าน เพื่อให้เด็กรักการอ่านด้วยตัวเขาเอง”<br>(จิระนันท์ พิตรปรีชา)";
const S8_P5 = "“…เจดีย์ชเวดากอง (Shwedagon Pagoda) เป็น 1 ใน 5 สิ่งศักดิ์สิทธิ์ที่สุดของชาวพม่า เป็นเจดีย์สีทองขนาดใหญ่ที่บรรจุพระเกศาธาตุรวมทั้งหมด 8 เส้นด้วยกัน คำว่า ‘ชเว’ แปลว่า ทอง ส่วนคำว่า ‘ดากอง’ หรือ ‘ตะเกิง’ ก็คือชื่อเดิมของเมืองย่างกุ้งนั่นเอง เจดีย์ชเวดากอง จึงหมายถึง เจดีย์ทองคำแห่งเมืองดากอง<br><br>ตามตำนานที่เล่าต่อ ๆ กันมาว่า เจดีย์ชเวดากองได้ถูกสร้างขึ้นเมื่อราว ๆ 2,500 กว่าปีก่อน โดยมีสองพี่น้องวานิช ชื่อว่า ตปุสสะ และภัลลิกะ ได้มีโอกาสเข้าเฝ้าพระพุทธเจ้า ด้วยความดีของสองพี่น้อง พระองค์จึงได้ประทานพระเกศาให้ 8 เส้น ทั้งสองพี่น้องจึงได้อัญเชิญมายังบนเนินเขา เสนคุตตระ จากนั้นพระเจ้าโอกะลับ จึงได้ทรงสร้างเจดีย์ครอบพระเกศาทั้ง 8 เส้น ต่อมาได้มีกษัตริย์มอญและกษัตริย์พม่าให้มีการต่อเติมบูรณะเพิ่มเติมอีกหลายครั้งจนมีขนาดใหญ่เท่าปัจจุบัน ที่นี่มีบริเวณกว้างขวางทำให้เจดีย์ชเวดากองโดดเด่นเห็นได้ชัดแม้อยู่ไกล<br><br>ไม่เพียงมีแต่เจดีย์ชเวดากองเท่านั้น ยังมีเจดีย์ขนาดน้อยใหญ่เรียงรายสวยงามราวกับอยู่เมืองสวรรค์ อาจจะยังไม่มีใครทราบว่าบนยอดของเจดีย์ชเวดากองมีเครื่องประดับมากมายที่เรามองไม่เห็น บนยอดเจดีย์มีการประดับด้วยเพชรจำนวน 4,531 เม็ด ยังมีทับทิม ไพลิน และบุษราคัมอีก 2,317 เม็ด รวมทั้งระฆังทองอีกจำนวน 1,06 ใบ ส่วนบนยอดสุดที่มีปลายแหลมมีเพชรเม็ดใหญ่เท่าฝ่ามือหนัก 72 กะรัต 1 เม็ด ประดับอยู่...”";
const S8_P7 = "“... โรคสมาธิสั้น คือ กลุ่มอาการที่ประกอบด้วยการขาดสมาธิ ควบคุมตนเองต่ำ และซุกซน อยู่ไม่นิ่ง อาการเหล่านี้เกิดขึ้นก่อนอายุ 7 ขวบ ส่งผลกระทบต่อพฤติกรรม อารมณ์ การเรียน และการปรับตัวเข้าสังคม อาการของเด็กแต่ละคนแตกต่างกัน บางรายมีอาการซน อยู่ไม่นิ่ง และควบคุมตนเองต่ำเป็นอาการหลัก บางคนอาจจะมีอาการขาดสมาธิเป็นปัญหาหลัก พบทั่วโลก ในประเทศไทยพบ 3-5% ของเด็กในวัย<br><br>สาเหตุของโรคสมาธิสั้นเกิดจากความบกพร่องของสารเคมีที่สำคัญบางตัวในสมอง โดยมีกรรมพันธุ์เป็นปัจจัยที่สำคัญ ปัจจัยจากการเลี้ยงดูหรือสิ่งแวดล้อมเป็นเพียงปัจจัยที่ทำให้อาการหรือความผิดปกติดีขึ้นหรือแย่ลง มารดาที่ขาดสารอาหาร ดื่มสุรา สูบบุหรี่ หรือถูกสารพิษบางชนิด เช่น ตะกั่ว ในระหว่างตั้งครรภ์ จะมีโอกาสมีลูกเป็นโรคสมาธิสั้นสูงขึ้น 30-40% ของเด็ก สมาธิสั้น จะพบความบกพร่องในทักษะการเรียน (learning Disorders) ร่วมด้วย<br><br>ข้อแนะนำสำหรับครูในการช่วยเหลือเด็กสมาธิสั้น<br>1. จัดให้เด็กนั่งหน้าหรือใกล้ครูให้มากที่สุดในขณะสอน<br>2. จัดให้เด็กนั่งให้ไกลจากประตู หน้าต่าง<br>3. เขียนการบ้านหรืองานที่เด็กต้องทำในชั้นเรียนให้ชัดเจนบนกระดานดำ<br>4. ตรวจสมุดจดงานของเด็กเพื่อให้แน่ใจว่าเด็กจดงานได้ครบ<br>5. อย่าสั่งงานให้เด็กทำ พร้อมกันทีเดียวหลายอย่าง ให้เด็กทำงานเสร็จทีละอย่าง ก่อนให้คำสั่งต่อไป<br>6. คิดรูปแบบวิธีเตือนหรือเรียกให้เด็กกลับมาสนใจบทเรียนโดยไม่ให้เด็กเสียหน้า<br>7. เพิ่มงานที่ใช้แรงสำหรับกลุ่มที่อยู่ไม่นิ่ง เช่น เพิ่มเวลาเล่นกีฬา มอบหมายหน้าที่ให้ลบกระดานช่วย ครูแจกงานให้ทำกิจกรรมที่ใช้แรง ให้เป็นนักกีฬาวิ่งเร็ว เป็นต้น<br>8. ชมหรือรางวัลเมื่อเด็กทำตัวดีหรือทำสิ่งที่เป็นประโยชน์ทันที<br>9. หลีกเลี่ยงการตำหนิ ว่ากล่าวรุนแรงหรือทำให้อาย ขายหน้า หรือการลงโทษทางร่างกาย (ตี) เมื่อเด็กทำผิด<br>10. เมื่อเด็กทำผิดพลาด ควรใช้วิธีการตัดคะแนน งดเวลาพัก ทำเวรหรืออยู่ต่อหลังเลิกเรียน (เพื่อทำงานที่ค้างอยู่ให้เสร็จ)<br>11. ให้เวลากับเด็กนานขึ้นกว่าเด็กปกติระหว่างการสอบ”";

// ---------- บทความประกอบโจทย์ ชุดที่ 9-10 ----------
const S9_P1 = "<b>รอยพ่นสีบนกำแพง</b><br><br><i>จดหมายฉบับที่ 1</i><br>ฉันเดือดดาลไปด้วยความโกรธที่เห็นกำแพงในโรงเรียนต้องถูกทำความสะอาดและทาสีใหม่ถึงสี่ครั้งเพื่อลดรอยพ่นสีบนกำแพง การสร้างสรรค์เป็นสิ่งที่น่าชื่นชมก็จริงอยู่ แต่มนุษย์ควรหาวิธีแสดงออกที่ไม่ต้องทำให้สังคมเดือดร้อนและสูญเสียค่าใช้จ่ายเพิ่มโดยไม่จำเป็น<br>ทำไมคุณชอบทำลายชื่อเสียงของคนวัยรุ่นหนุ่มสาวด้วยการไปพ่นสีบนกำแพง ซึ่งเป็นข้อห้าม ศิลปินมืออาชีพน่ะ เขาไม่แขวนงานของเขาตามข้างถนนหรอก จริงไหมแต่เขาจะหาเงินและชื่อเสียงโดยการแสดงนิทรรศการผลงานอย่างถูกต้องตามกฎหมาย<br>ในความเห็นของฉันไม่ว่าจะเป็นตัวตึก รั้ว ม้านั่งในสวนสาธารณะ ต่างก็ถูกออกแบบมาอย่างมีศิลปะในตัวเองแล้วทั้งนั้น มันน่าเสียดายที่จะไปทำลายงานสถาปัตยกรรมนี้เสีย ด้วยรอยพ่นสี และยิ่งกว่านั้น วิธีนี้ยังทำลายชั้นโอโซนของมันในบรรยากาศอีกด้วยจริง ๆ นะ ฉันไม่เข้าใจเลยว่าทำไมศิลปินอาชญากรรมเหล่านี้จะรู้สึกเดือดร้อนเมื่อเห็นว่า “งานศิลปะ” ของพวกเขาถูกล้างออกครั้งแล้วครั้งเล่า<br><i>เกวลิน</i><br><br><i>จดหมายฉบับที่ 2</i><br>ไม่ต้องพูดกันเรื่องรสนิยม ทุกวันนี้สังคมเต็มไปด้วยการสื่อสารและการโฆษณา ตามถนนมีแต่ตราของบริษัท ชื่อห้างร้าน โปสเตอร์ขนาดมหึมา สิ่งเหล่านี้เป็นสิ่งที่ยอมรับได้ใช่ไหม ใช่ ส่วนใหญ่รองรับกันได้ แล้วรอยพ่นสีบนกำแพงล่ะ ยอมรับกันได้ไหม บางคนก็บอกว่าได้ บางคนก็บอกว่าไม่ได้<br>ใครเป็นคนจ่ายค่าพ่นสีกำแพง ในที่สุดใครเป็นคนจ่ายค่าโฆษณา ใช่ผู้บริโภคไงล่ะ<br>คนที่เอาแผ่นป้ายโฆษณามาเที่ยวแปะล่ะ เคยขออนุญาตไหม ก็ไม่เคย พวกพ่นสีบนกำแพงทำเช่นนั้นบ้างได้ไหม มันไม่ใช่แต่เรื่องของการบอกชื่อของตนเอง-ชื่อแก๊งและผลงานศิลปะขึ้นใหญ่ ๆ ตามข้างถนน<br>ลองนึกถึงผ้าลายทางและลายตาหมากรุกที่มีขายตามร้านเมื่อสองสามปีก่อน และเสื้อผ้าของนักเล่นสกี ทั้งลายและสีของผ้าเหล่านี้ถูกขโมยมาจากลายที่ตกแต่งไว้อย่างสวยงามบนกำแพงคอนกรีตตามข้างถนนนั้นเอง ตลกดีที่ลวดลายเหล่านี้เป็นที่ยอมรับและชื่นชม แต่รอยพ่นสีบนกำแพงซึ่งเป็นแบบเดียวกันกลับถูกมองเห็นว่าทุเรศ<br>โลกนี้มันช่างยากนักสำหรับศิลปิน<br><i>โสภิกา</i><br><br>จดหมายสองฉบับนี้เกี่ยวข้องกับเรื่องรอยพ่นสีบนกำแพง ที่ได้มาจากอินเทอร์เน็ต รอยพ่นสีบนกำแพงเป็นการวาดภาพ และขีดเขียนบนกำแพงที่ผิดกฎหมาย";
const S9_P2 = "<b>มาซอนโด</b><br>ด้วยความละลานตาของสิ่งประดิษฐ์ที่น่าพิศวง ชาวเมืองมาซอนโดไม่รู้ด้วยซ้ำว่าความมหัศจรรย์นั้นเริ่มต้นจากตรงไหน พวกเขายอมอดหลับอดนอนทั้งคืนเพื่อจ้องดูหลอดไฟสีนวล ที่มีกระแสไฟป้อนมาจากเครื่องปั่นไฟออร์เลียโน ทริสเต บรรทุกมากับรถไฟเที่ยวที่สอง และพยายามทนเพื่อให้คุ้นกับเสียง ตูม ตูม ของเครื่องประหลาดนั้น ต่อมาพวกเขาก็เริ่มไม่พอใจกับการชมภาพยนตร์ที่เคลื่อนไหวเหมือนมีชีวิตที่ ดอน บรูโน เครสปี พ่อค้าผู้ร่ำรวยนำมาฉายในโรงฉายที่มีช่องขายตั๋วทำเป็นหัวสิงโต เพราะว่าตัวละครที่ตายและถูกฝังแล้วในเรื่องหนึ่ง ซึ่งพวกเขาได้เศร้าโศกและเสียน้ำตาไปอย่างมาก กลับมีชีวิตขึ้นมาและกลายเป็นชาวอาหรับในเรื่องใหม่ ผู้ชมต้องจ่ายเงินสองเซ็นตาโวเป็นค่าตั๋วเข้าชมเพื่อร่วมเสียใจกับความทุกข์ยากของตัวละคร พวกเขาไม่ยอมถูกหลอกให้ทุกข์ใจไม่จริงอีกต่อไป จึงแสดงความโกรธด้วยการทุบทำลายเก้าอี้ ดอน บรูโน เครสปี ได้ขอร้องให้นายกเทศมนตรีช่วยประกาศว่า ภาพยนตร์เป็นเพียงภาพลวงตา ไม่ควรนำมาเป็นอารมณ์ และไม่มีค่าการที่ผู้ชมจะระเบิดความโกรธแค้น จากคำชี้แจงที่เตือนสติเองทำให้หลายคนรู้สึกว่าตนตกเป็นเหยื่อของธุรกิจหนังเร่ จึงตัดสินใจไม่ดูภาพยนตร์อีก เพราะคิดว่าตัวเองก็มีความทุกข์ยากมากเกินกว่าที่จะไปร้องไห้ให้กับสิ่งที่เป็นเพียงภาพลวงตาเหล่านั้น";
const S9_P3 = "<b>ป้ายประกาศในซุปเปอร์มาร์เก็ต</b><br><br><b>การแจ้งเตือนการแพ้ถั่วลิสง<br>ขนมปังกรอบไส้ครีมมะนาว</b><br><b>วันที่แจ้งเตือน</b> : 4 กุมภาพันธ์<br><b>ชื่อผู้ผลิต</b> : บริษัท ไฟน์ฟู้ดส์ จำกัด<br><b>ข้อมูลผลิตภัณฑ์</b> : ขนมปังกรอบไส้ครีมมะนาว 125 กรัม (ควรบริโภคก่อน 18 มิถุนายน และควรบริโภคก่อน 1 กรกฎาคม)<br><b>รายละเอียด</b> : ขนมปังกรอบบางอย่างในรุ่นการผลิตเหล่านี้ อาจมีส่วนของถั่วลิสงผสมอยู่ แต่ไม่ได้แจ้งไว้ในรายการส่วนผสม คนที่แพ้ถั่วไม่ควรรับประทานขนมปังกรอบนี้<br><b>การปฏิบัติของผู้บริโภค</b> : ถ้าท่านซื้อขนมปังกรอบนี้ไป ท่านสามารถนำมาคืน ณ ที่ที่ท่านซื้อ เพื่อรับเงินคืนได้เต็มจำนวน หรือโทรสอบถามข้อมูลเพิ่มเติมได้ที่ 1800-034-241";
const S9_P4 = "<b>ประกาศ เรื่องการบริจาคโลหิต</b><br>การบริจาคโลหิตเป็นสิ่งจำเป็น ไม่คนที่แพ้ถั่วไม่ควรรับประทานขนมปังกรอบนี้ด้อย่างสมบูรณ์ ดังนั้น การบริจาคโลหิตจึงไม่มีอะไรมาชดเชยได้และจำเป็นสำหรับการช่วยชีวิต ในฝรั่งเศส แต่ละปีมีผู้ป่วย 500,000 คน ได้รับประโยชน์จากการถ่ายเลือด<br><b>อุปกรณ์ที่ใช้เจาะเลือดผ่านการฆ่าเชื้อและใช้ครั้งเดียว (กระบอกฉีดยา สายยาง ถุงใส่เลือด) ไม่มีความเสี่ยงใด ๆ ในการให้เลือดของคุณ</b><br><br><b>การบริจาคโลหิต :</b><br>เป็นรูปแบบของการบริจาคที่รู้จักกันดีที่สุด และใช้เวลา 45 นาที ถึง 1 ชั่วโมง<br>ถุงความจุ 450 มิลลิลิตร ถูกเก็บไปพร้อมกับตัวอย่างอีกเล็กน้อยสำหรับทดสอบและตรวจสอบ<br>- ผู้ชายสามารถบริจาคโลหิตได้ปีละ 5 ครั้ง ผู้หญิงปีละ 3 ครั้ง<br>- ผู้บริจาคต้องมีอายุตั้งแต่ 18 ถึง 65 ปี<br>จำเป็นต้องเว้นระยะอย่างน้อย 8 สัปดาห์ ระหว่างการบริจาคโลหิตแต่ละครั้ง";
const S9_MAP = "<b>ผังห้องสมุด</b><br><img src=\"data:image/jpeg;base64,\" style=\"max-width:100%;height:auto\">";
const S9_METRO = "<b>รถไฟใต้ดิน</b><br><img src=\"data:image/jpeg;base64,\" style=\"max-width:100%;height:auto\">";
const S10_P1 = "<b>ทะเลสาบชาด</b><br>รูปที่ 1 แสดงการเปลี่ยนแปลงระดับน้ำของทะเลสาบชาด ในซาฮารา อัฟริกาเหนือ ทะเลสาบชาดสูญหายไร้ร่องรอย ประมาณ 20,000 ปีก่อนคริสตศักราช (20,000 BC) ช่วงปลายยุคน้ำแข็ง และประมาณ 11,000 ปีก่อนคริสตศักราช (11,000 BC) ทะเลสาบนี้ปรากฏขึ้นมาอีกครั้ง ปัจจุบันระดับน้ำของทะเลสาบมีระดับเดียวกับเมื่อปี ค.ศ. 1000 (AD 1,000)<br>รูปที่ 2 แสดงถึงศิลปะบนหินแห่งซาฮารา (ภาพเขียนโบราณหรือภาพวาดบนฝาผนังถ้ำ) และการเปลี่ยนแปลงของชีวิตสัตว์ป่า";
